css:
.absolute {
  position: absolute;
}
.relative {
  position: relative;
}
.left-\[13px\] {
  left: 13px;
}
.right-\[13px\] {
  right: 13px;
}
.inline-flex {
  display: inline-flex;
}
.hidden {
  display: none;
}
.h-6 {
  height: 1.5rem;
}
.h-\[50px\] {
  height: 50px;
}
.w-6 {
  width: 1.5rem;
}
.w-\[110px\] {
  width: 110px;
}
.items-center {
  align-items: center;
}
.rounded-full {
  border-radius: 9999px;
}
.bg-white {
  --tw-bg-opacity: 1;
  background-color: rgb(255 255 255 / var(--tw-bg-opacity));
}
.from-orange-500 {
  --tw-gradient-from: #f97316 var(--tw-gradient-from-position);
  --tw-gradient-to: rgb(249 115 22 / 0) var(--tw-gradient-to-position);
  --tw-gradient-stops: var(--tw-gradient-from), var(--tw-gradient-to);
}
.to-yellow-400 {
  --tw-gradient-to: #facc15 var(--tw-gradient-to-position);
}
.fill-black {
  fill: #000;
}
.fill-white {
  fill: #fff;
}
.opacity-60 {
  opacity: 0.6;
}
.shadow-sm {
  --tw-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --tw-shadow-colored: 0 1px 2px 0 var(--tw-shadow-color);
  box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000),
    var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow);
}
.duration-300 {
  transition-duration: 300ms;
}
.after\:absolute::after {
  content: var(--tw-content);
  position: absolute;
}
.after\:left-\[5px\]::after {
  content: var(--tw-content);
  left: 5px;
}
.after\:top-\[5px\]::after {
  content: var(--tw-content);
  top: 5px;
}
.after\:h-\[40px\]::after {
  content: var(--tw-content);
  height: 40px;
}
.after\:w-\[40px\]::after {
  content: var(--tw-content);
  width: 40px;
}
.after\:rounded-full::after {
  content: var(--tw-content);
  border-radius: 9999px;
}
.after\:bg-gradient-to-r::after {
  content: var(--tw-content);
  background-image: linear-gradient(to right, var(--tw-gradient-stops));
}
.after\:shadow-md::after {
  content: var(--tw-content);
  --tw-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --tw-shadow-colored: 0 4px 6px -1px var(--tw-shadow-color),
    0 2px 4px -2px var(--tw-shadow-color);
  box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000),
    var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow);
}
.after\:duration-300::after {
  content: var(--tw-content);
  transition-duration: 300ms;
}
.after\:content-\[\'\'\]::after {
  --tw-content: "";
  content: var(--tw-content);
}
.active\:after\:w-\[50px\]:active::after {
  content: var(--tw-content);
  width: 50px;
}
.peer:checked ~ .peer-checked\:bg-zinc-500 {
  --tw-bg-opacity: 1;
  background-color: rgb(113 113 122 / var(--tw-bg-opacity));
}
.peer:checked ~ .peer-checked\:fill-white {
  fill: #fff;
}
.peer:checked ~ .peer-checked\:opacity-60 {
  opacity: 0.6;
}
.peer:checked ~ .peer-checked\:opacity-70 {
  opacity: 0.7;
}
.peer:checked ~ .peer-checked\:after\:left-\[105px\]::after {
  content: var(--tw-content);
  left: 105px;
}
.peer:checked ~ .peer-checked\:after\:translate-x-\[-100\%\]::after {
  content: var(--tw-content);
  --tw-translate-x: -100%;
  transform: translate(var(--tw-translate-x), var(--tw-translate-y))
    rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y))
    scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y));
}
.peer:checked ~ .peer-checked\:after\:from-zinc-900::after {
  content: var(--tw-content);
  --tw-gradient-from: #18181b var(--tw-gradient-from-position);
  --tw-gradient-to: rgb(24 24 27 / 0) var(--tw-gradient-to-position);
  --tw-gradient-stops: var(--tw-gradient-from), var(--tw-gradient-to);
}
.peer:checked ~ .peer-checked\:after\:to-zinc-900::after {
  content: var(--tw-content);
  --tw-gradient-to: #18181b var(--tw-gradient-to-position);
}
